	shuffle($accounts);
	shuffle($accounts);

	$pt = [];
	$ft = [];

	foreach($accounts as $account){
		if($account['type'] == 1){
			$pt[] = $account;
		}elseif($account['type'] == 2){
			$ft[] = $account;
		}
	}

	shuffle($pt);
	shuffle($pt);
	shuffle($ft);
	shuffle($ft);

	while(true){
		$pt_grps = [];
		$bunch = [];
		
		foreach($pt as $pt_student){
			if(count($bunch) == 6){ //If 6 in group, add to groups and reset
				$pt_grps[] = $bunch;
				$bunch = [];
			}elseif(count($bunch) == 5){ //If 5 in group
				if(rand(0,1) == 0){ //If rand false, reset add to groups and reset
					$pt_grps[] = $bunch;
					$bunch = [];
				}
			}
			
			$bunch[] = $pt_student['id'];
		}
		
		if(count($bunch) >= 5){
			$pt_grps[] = $bunch;
			break;
		}
	}

	while(true){
		$ft_grps = [];
		$bunch = [];
		
		foreach($ft as $ft_student){
			if(count($bunch) == 6){ //If 6 in group, add to groups and reset
				$ft_grps[] = $bunch;
				$bunch = [];
			}elseif(count($bunch) == 5){ //If 5 in group
				if(rand(0,1) == 0){ //If rand false, reset add to groups and reset
					$ft_grps[] = $bunch;
					$bunch = [];
				}
			}
			
			$bunch[] = $ft_student['id'];
		}
		
		if(count($bunch) >= 5){
			$ft_grps[] = $bunch;
			break;
		}
	}
	
	echo "Number of PT students = ". array_sum(array_map("count", $pt_grps)) ."<br />";
	echo "Number of PT groups = ". count($pt_grps) ."<br /><br />";
	
	echo "Number of FT students = ". array_sum(array_map("count", $ft_grps)) ."<br />";
	echo "Number of FT groups = ". count($ft_grps) ."<br /><br />";

	$add_grps = "INSERT INTO `groups` (`members`) VALUES <br />";

	foreach($pt_grps as $grp){
		$add_grps .= "('" .addslashes(json_encode($grp)) ."'),<br />";
	}

	foreach($ft_grps as $key => $grp){
		if($key !== array_key_last($ft_grps)){
			$add_grps .= "('" .addslashes(json_encode($grp)) ."'),<br />";
		}else{
			$add_grps .= "('" .addslashes(json_encode($grp)) ."');";
		}
	}

	echo $add_grps;
